 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,audio_path,audio_sha256,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-listening-l20-v1','0.1.0','Listening Lesson 10 step 6 of 6: Mixed check','listening','independent_check','targeted-listening-06/a5331a1cfeeb7128eaf2f600bda7931adff4215cec9e47098dd9eef11ce6d5dd/l20/BH-TL06-L10F_v1.mp3','a5331a1cfeeb7128eaf2f600bda7931adff4215cec9e47098dd9eef11ce6d5dd','You will hear part of a lecture about the design of queues. Read LEARN FIRST and the worked example. Then listen to the whole lecture ONCE, without pausing, and answer six new questions (a short practice check, not a full IELTS test). Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use everything: follow the signposts, wait for the confirmed answer, match meaning not words, and write the exact word you hear.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Separate lines: customers kept ________ their own line with the others", "accepted_answers": ["comparing"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "fe66c90a-e788-44f7-8caa-4e0019026729", "answer_format": "text"}, {"id": "q2", "prompt": "Why do people find a single line easier to accept?", "accepted_answers": ["A"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "options": [{"value": "A", "label": "A  It seems fairer."}, {"value": "B", "label": "B  Customers can sit down."}, {"value": "C", "label": "C  There are more counters."}, {"value": "D", "label": "D  It is always faster."}]}, {"id": "q3", "prompt": "In the class poll, most people guessed that their wait was ...", "accepted_answers": ["B"], "taxonomy_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "supporting_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "options": [{"value": "A", "label": "A  about fifty per cent too long"}, {"value": "B", "label": "B  about twice as long as it really was"}, {"value": "C", "label": "C  exactly right"}, {"value": "D", "label": "D  shorter than it really was"}]}, {"id": "q4", "prompt": "Once customers are choosing their ________, they feel the experience has begun", "accepted_answers": ["meal"], "taxonomy_node_id": "19e4299c-70f4-4d30-8726-4416be272056", "supporting_node_id": "1b02bd3d-3b53-4357-ad5b-3e31e3c5f5bd", "answer_format": "text"}, {"id": "q5", "prompt": "Why do most venues now send a message to the customer''s phone?", "accepted_answers": ["C"], "taxonomy_node_id": "610d8325-5a22-4df9-beb0-aa512ff82374", "supporting_node_id": "59fbf038-1ceb-48b0-b905-b7f78a8076e3", "options": [{"value": "A", "label": "A  Customers asked for it."}, {"value": "B", "label": "B  Pagers were too expensive."}, {"value": "C", "label": "C  Too many pagers went missing."}, {"value": "D", "label": "D  Phones are faster than pagers."}]}, {"id": "q6", "prompt": "What does the lecturer say about virtual queues?", "accepted_answers": ["B"], "taxonomy_node_id": "472c05b5-8cc0-43b8-b300-ae5b769d7769", "supporting_node_id": "4bdeaffb-7390-4b00-9955-69b9da537007", "options": [{"value": "A", "label": "A  They only work in restaurants."}, {"value": "B", "label": "B  They do not remove the wait but change how it feels."}, {"value": "C", "label": "C  They make the wait longer."}, {"value": "D", "label": "D  They remove the wait completely."}]}]'::jsonb,'{"scope": "Targeted IELTS listening exercise; not a full paper or an official IELTS recording.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-listening-targeted-focus-v1", "passage": "LEARN FIRST: the whole routine\n\n1. Before you listen, read the questions and predict the word type or the idea.\n2. Follow the signposts so you always know which point the lecturer is on.\n3. Do not write the first thing you hear: wait for the confirmed answer.\n4. For gaps, write ONE word you hear, spelled correctly.\n\nWORKED EXAMPLE\nNote: ''Early virtual queues used electronic ________.''\nYou hear: ''Early systems handed out electronic pagers''.\nPlural noun after ''electronic''. -> pagers\n\nNow listen once and answer six new questions on your own.", "focus": "Part 4 lecture: signposts, distractors, paraphrased notes and main ideas in one check."}'::jsonb || jsonb_build_object('teacher_notes', '1 comparing: "customers kept comparing their own line with the others". After ''kept'' you need the -ing form.
2 A, "people consider the system fairer, and that sense of fairness makes the wait easier to accept".
3 B, "most people guessed roughly double their real wait". Fifty per cent was only the lecturer''s prediction.
4 meal: "once you''re choosing your meal, you feel the experience has already begun".
5 C, "so many of these went missing that most venues now simply send a message to the customer''s own phone".
6 B, "It doesn''t remove the wait, of course, but it changes how the wait feels".
